module tst_bench_top();

// === Global Sync Signal ===
reg llm_go_signal = 1;


	//
	// wires && regs
	//
	reg  clk;
//	reg instrumented_clk = 0;
	reg  rstn;

	wire [31:0] adr;
	wire [ 7:0] dat_i, dat_o;
	wire we;
	wire stb;
	wire cyc;
	wire ack;
	wire inta;

	reg [1:0] cpol, cpha;
	reg [2:0] e;

	wire sck, mosi, miso;
	reg [7:0] q;

	parameter SPCR = 2'b00;
	parameter SPSR = 2'b01;
	parameter SPDR = 2'b10;
	parameter SPER = 2'b11;

	//
	// Module body
	//
	integer n;
integer file_mantra;
	// generate clock
	always #5 clk = ~clk;
	//always #5 instrumented_clk = ~instrumented_clk;

	// hookup wishbone master model
	wb_master_model #(8, 32) u0 (
		.clk (clk),
		.rst (rstn),
		.adr (adr),
		.din (dat_i),
		.dout(dat_o),
		.cyc (cyc),
		.stb (stb),
		.we  (we),
		.sel (),
		.ack (ack),
		.err (1'b0),
		.rty (1'b0)
	);

	// hookup spi core
	simple_spi_top spi_top (
		// wishbone interface
		.clk_i (clk),
		.rst_i (rstn),
		.cyc_i (cyc),
		.stb_i (stb),
		.adr_i (adr[1:0]),
		.we_i  (we),
		.dat_i (dat_o),
		.dat_o (dat_i),
		.ack_o (ack),
		.inta_o(inta),

		.sck_o (sck),
		.mosi_o(mosi),
		.miso_i(miso)
	);

	// hookup spi slave model
	spi_slave_model spi_slave (
		.csn(1'b0),
		.sck(sck),
		.di(mosi),
		.do_1(miso)
	);
//	integer f;
	initial begin
	      `ifdef WAVES
	         $shm_open("waves");
	         $shm_probe("AS",tst_bench_top,"AS");
	         $display("INFO: Signal dump enabled ...\n\n");
	      `endif

//	      force spi_slave.debug = 1'b1; // enable spi_slave debug information
	      force spi_slave.debug = 1'b0; // disable spi_slave debug information

	      $display("\nstatus: %t Testbench started\n\n", $time);


	      // initially values
	      clk = 0;
		//  instrumented_clk = 0;
		 // f = $fopen("output.txt");
		 // $fwrite(f, "time,dat_o\n");
wait(llm_go_signal == 0);
clk = 0;
force spi_slave.debug = 1'b0; // disable spi_slave debug information

	      $display("\nstatus: %t Testbench started\n\n", $time);

	      // reset system
	      rstn = 1'b1; // negate reset
	      #2;
	      rstn = 1'b0; // assert reset
	      repeat(1) @(posedge clk);
	      rstn = 1'b1; // negate reset

	      $display("status: %t done reset", $time);

	      @(posedge clk);

	      //
	      // program core
	      //
	      for (cpol=0; cpol<=1; cpol=cpol+1)
	      for (cpha=0; cpha<=1; cpha=cpha+1) 
	      for (e=0; e<=3; e=e+1)
	      begin
	          //set cpol/cpha in spi slave model
	          force spi_slave.cpol=cpol[0];
	          force spi_slave.cpha=cpha[0];
	          $display("cpol:%b, cpha:%b, e:%b", cpol[0],cpha[0],e[1:0]);

	          // program internal registers

	          // load control register
	          u0.wb_write(1, SPCR, {4'b0101,cpol[0],cpha[0],e[1:0]} );
	          //verify control register
	          u0.wb_cmp  (0, SPCR, {4'b0101,cpol[0],cpha[0],e[1:0]} );


	          // load extended control register
	          u0.wb_write(1,SPER,8'h0);
	          //verify extended control register
	          u0.wb_cmp (0,SPER,8'h0);

	          //fill memory
	          for(n=0;n<8;n=n+1) begin
	            u0.wb_write(1,SPDR,{cpol[0],cpha[0],e[1:0],n[3:0]});
	            //wait for transfer to finish
	            u0.wb_read(1,SPSR,q);
	            while(~q[7]) u0.wb_read(1,SPSR,q);
	            //clear 'spif' bit
	            u0.wb_write(1,SPSR,8'h80);
	          end

	          //verify memory
	          for(n=0;n<8;n=n+1) begin
	            u0.wb_write(1,SPDR,~n);
	            //wait for transfer to finish
	            u0.wb_read(1,SPSR,q);
	            while(~q[7]) u0.wb_read(1,SPSR,q);
	            //clear 'spif' bit
	            u0.wb_write(1,SPSR,8'h80);
	            //verify memory content
	            u0.wb_cmp(0,SPDR,{cpol[0],cpha[0],e[1:0],n[3:0]});
	          end
	      end

	      // check tip bit
//	      u0.wb_read(1, SR, q);
//	      while(q[1])
//	      u0.wb_read(1, SR, q); // poll it until it is zero
//	      $display("status: %t tip==0", $time);

	       #250000; // wait 250us
	      $display("\n\nstatus: %t Testbench done", $time);
		  //$fclose(f);
		  if (file_mantra != 0) $fclose(file_mantra);
	      $finish;
	  end
  //  always @(posedge instrumented_clk)
  //   $fwrite(f, "%0d,%x\n", $time,dat_o);
///////////////////added

        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      // $fwrite(file_mantra, "adr,");
      $fwrite(file_mantra, "dat_o,");
      // $fwrite(file_mantra, "cyc,");
      // $fwrite(file_mantra, "stb,");
      // $fwrite(file_mantra, "dat_i,");
      // $fwrite(file_mantra, "ack,");
      // $fwrite(file_mantra, "inta,");
      // $fwrite(file_mantra, "sck,");
      // $fwrite(file_mantra, "mosi,");
      // $fwrite(file_mantra, "miso,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            //#5
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        // $fwrite(file_mantra, "%h, ", adr);
        $fwrite(file_mantra, "%h, ", dat_o);
        // $fwrite(file_mantra, "%h, ", cyc);
        // $fwrite(file_mantra, "%h, ", stb);
        // $fwrite(file_mantra, "%h, ", dat_i);
        // $fwrite(file_mantra, "%h, ", ack);
        // $fwrite(file_mantra, "%h, ", inta);
        // $fwrite(file_mantra, "%h, ", sck);
        // $fwrite(file_mantra, "%h, ", mosi);
        // $fwrite(file_mantra, "%h, ", miso);

            $fwrite(file_mantra, "\n");
          end
        end
		  // initial begin
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

