initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [7:0] my_status;
        reg [7:0] read_back;
        reg [7:0] expected_val;

    // 1. DECLARE VARIABLES FIRST





    // 2. WAIT for original tests (Handshake)
    wait(llm_go_signal == 1);

    $display("LLM: Starting Mutation Tests...");

    // 3. Reset DUT
    // Ensure DUT is in a known state before starting
    rstn = 1'b0;
    #200;
    rstn = 1'b1;
    #200;

    // ---------------------------------------------------------
    // TEST 1: FIFO Boundary & Flags (Targeting fifo4.v)
    // ---------------------------------------------------------
    // Configure SPI for slow speed to allow FIFO filling via Wishbone
    // SPCR (0x00): SPE=1, MSTR=1, SPR=11 (div 32) -> 8'h53
    u0.wb_write(1, 0, 8'h53);
    // SPER (0x03): SPRE=11 (div 128) -> 8'h03. Total div very slow.
    u0.wb_write(1, 3, 8'h03);

    // Check Empty Flags (SPSR: 0x01)
    // Expect WFEMPTY(2)=1, RFEMPTY(0)=1 -> Mask 0x05 should be 0x05
    u0.wb_read(1, 1, my_status);
    if ((my_status & 8'h05) != 8'h05) 
        $display("LLM Error: FIFO not empty initially. Status: %h", my_status);

    // Fill Write FIFO (4 entries)
    // Use walking 1s patterns to test data lines and FIFO storage
 // --- 改进后的 TEST 1 ---
u0.wb_write(1, 0, 8'h03); // SPE=0, 先关闭使能，只设置速率
#10;
// 现在写入 4 个，它们会老老实实呆在 FIFO 里
u0.wb_write(1, 2, 8'h01);
u0.wb_write(1, 2, 8'h02);
u0.wb_write(1, 2, 8'h04);
u0.wb_write(1, 2, 8'h08);

u0.wb_read(1, 1, my_status);
// 此时 SPI 没开，FIFO 必然是满的
if ((my_status & 8'h08) != 8'h08) $display("FIFO Full Success!");

    // Check Full Flag (SPSR: 0x01)
    // Expect WFFULL(3)=1 -> Mask 0x08 should be 0x08.
    u0.wb_read(1, 1, my_status);
    if ((my_status & 8'h08) != 8'h08) 
        $display("LLM Error: FIFO not full after 4 writes. Status: %h", my_status);

    // Cause Overrun (Write 5th byte)
    u0.wb_write(1, 2, 8'h10);

    // Check Write Collision (WCOL bit 6 in SPSR)
    u0.wb_read(1, 1, my_status);
    if ((my_status & 8'h40) != 8'h40) 
        $display("LLM Error: WCOL not set on overrun. Status: %h", my_status);

    // Clear WCOL (Write 1 to bit 6 of SPSR)
    u0.wb_write(1, 1, 8'h40);
    u0.wb_read(1, 1, my_status);
    if ((my_status & 8'h40) != 8'h00) 
        $display("LLM Error: WCOL not cleared. Status: %h", my_status);

    // ---------------------------------------------------------
    // TEST 2: Data Integrity & Loopback (Targeting Shift Reg)
    // ---------------------------------------------------------
    // Reset Core (Disable SPE) to clear FIFOs
    u0.wb_write(1, 0, 8'h00); 
    #100;
    // Enable SPE, Fast Clock (SPR=00) -> 8'h50
    u0.wb_write(1, 0, 8'h50);
    u0.wb_write(1, 3, 8'h00);

    // Sync Slave Memory (Flush 8 bytes to wrap slave address pointer)
    for (i = 0; i < 8; i = i + 1) begin
        u0.wb_write(1, 2, 8'h00);
        my_status = 0;
        while (my_status[7] == 0) u0.wb_read(1, 1, my_status); // Wait SPIF
        u0.wb_write(1, 1, 8'h80); // Clear SPIF
        u0.wb_read(1, 2, read_back); // Drain RX FIFO
    end

    // Send Pattern 1: 0xAA (Alternating 10101010)
    u0.wb_write(1, 2, 8'hAA);
    my_status = 0;
    while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    u0.wb_write(1, 1, 8'h80);
    u0.wb_read(1, 2, read_back); // Discard (old data from slave)

    // Send Pattern 2: 0x55 (Alternating 01010101)
    u0.wb_write(1, 2, 8'h55);
    my_status = 0;
    while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    u0.wb_write(1, 1, 8'h80);
    u0.wb_read(1, 2, read_back); // Discard

    // Read Back Pattern 1 (0xAA) - Send dummy 0x00 to clock it out
    u0.wb_write(1, 2, 8'h00);
    my_status = 0;
    while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    u0.wb_write(1, 1, 8'h80);
    u0.wb_read(1, 2, read_back);
    if (read_back !== 8'hAA) $display("LLM Error: Data Mismatch. Exp AA, Got %h", read_back);

    // Read Back Pattern 2 (0x55) - Send dummy 0x00
    u0.wb_write(1, 2, 8'h00);
    my_status = 0;
    while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    u0.wb_write(1, 1, 8'h80);
    u0.wb_read(1, 2, read_back);
    if (read_back !== 8'h55) $display("LLM Error: Data Mismatch. Exp 55, Got %h", read_back);

    // ---------------------------------------------------------
    // TEST 3: Register Read/Write (Targeting Stuck-at Faults)
    // ---------------------------------------------------------
    // Write SPER with 0x55
    u0.wb_write(1, 3, 8'h55);
    u0.wb_cmp(0, 3, 8'h55);

    // Write SPER with 0xAA
    u0.wb_write(1, 3, 8'hAA);
    u0.wb_cmp(0, 3, 8'hAA);

    // ---------------------------------------------------------
    // Handover
    // ---------------------------------------------------------
    $display("LLM Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================
// === LLM Enhanced Stimuli (Optimized Version) ===
// initial begin
    // integer i;
    // reg [7:0] my_status;
    // reg [7:0] read_back;

    // // // 1. 等待系统稳定并握手
    // // wait(rstn === 1'b1);
    // wait(llm_go_signal == 1);
    // // #500; // 增加延迟，确保原始 TB 的初始化复位已彻底结束

    // $display("LLM: Starting Optimized Mutation Tests...");

    // // ---------------------------------------------------------
    // // TEST 1: FIFO Boundary & Flags (解决 FIFO 不满的问题)
    // // ---------------------------------------------------------
    // // 关键步骤：先关闭 SPE (Bit 6)，让数据在 FIFO 堆积
    // u0.wb_write(1, 0, 8'h13); // SPE=0, MSTR=1, SPR=11 (关闭使能但配置模式)
