    // // 现在检查 Full Flag (SPSR 位 3)
    // u0.wb_read(1, 1, my_status);
    // if ((my_status & 8'h08) == 8'h08) 
        // $display("LLM PASS: FIFO Full Flag detected.");
    // else 
        // $display("LLM FAIL: FIFO not full. Status: %h", my_status);

    // // 故意制造超限写入以触发 WCOL
    // u0.wb_write(1, 2, 8'h10);
    // u0.wb_read(1, 1, my_status);
    // if ((my_status & 8'h40) == 8'h40) 
        // $display("LLM PASS: WCOL (Collision) detected.");
    // else 
        // $display("LLM FAIL: WCOL not set. Status: %h", my_status);

    // // ---------------------------------------------------------
    // // TEST 2: Data Integrity (解决 Got 00 的问题)
    // // ---------------------------------------------------------
    // // 清空状态并重新使能 SPI
    // u0.wb_write(1, 1, 8'hC0); // 清除 SPIF 和 WCOL
    // u0.wb_write(1, 0, 8'h50); // SPE=1, 开启使能，进入正常工作模式
    // #200;

    // // 为了确保数据对齐，先发一个 Dummy Byte 激活 Slave
    // u0.wb_write(1, 2, 8'hFF); 
    // my_status = 0;
    // while (my_status[7] == 0) u0.wb_read(1, 1, my_status); // 等待发送完成
    // u0.wb_write(1, 1, 8'h80); // 必须写 1 清除 SPIF
    // u0.wb_read(1, 2, read_back); // 消耗掉 Dummy Read

    // // 发送 AA 并检查
    // u0.wb_write(1, 2, 8'hAA);
    // my_status = 0;
    // while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    // u0.wb_write(1, 1, 8'h80);
    // u0.wb_read(1, 2, read_back); // 这里的 read_back 是 Slave 对 0xAA 的响应

    // // 注意：如果是环回/Slave模型，通常需要再发一个 Dummy 读出刚才发进去的 AA
    // u0.wb_write(1, 2, 8'h00); 
    // while (my_status[7] == 0) u0.wb_read(1, 1, my_status);
    // u0.wb_write(1, 1, 8'h80);
    // u0.wb_read(1, 2, read_back);

    // if (read_back === 8'hAA) $display("LLM PASS: Data AA verified.");
